/* === SA shared shell base inlined from styles.css (page uses super_admin.css only) === */

@import url("https://fonts.googleapis.com/css2?family=Google+Sans+Flex:opsz,wght,ROND@8..144,100..900,0..100&display=swap");
@import url("https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@20..48,400,0,0&display=swap");
@import url("https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css");

:root {
  --admin-seller-font: "Google Sans Flex", "Segoe UI", Helvetica, Arial, sans-serif;
  --admin-sidebar-letter-spacing: -0.6px;
  color-scheme: light;
  /* Google Fonts Knowledge light tokens (fonts.google.com/knowledge). */
  --sa-page: #f2f2f2;
  --sa-rail: #f0f4f9;
  --sa-surface: #ffffff;
  --sa-surface-low: #f8fafc;
  --sa-surface-high: #e5e7eb;
  --sa-on-surface: #1f1f1f;
  --sa-on-variant: #444746;
  --sa-muted: #52607a;
  --sa-hint: #64748b;
  --sa-outline: #c4c7c5;
  --sa-outline-strong: #747775;
  --sa-hover: rgba(68, 71, 70, 0.08);
  --sa-nav-active-bg: var(--accent-soft);
  --sa-nav-active-fg: var(--accent-text);
  --sa-search-bg: #e5e5e5;
  --sa-switch-track: #cbd5e1;
  --sa-switch-knob: #ffffff;
  --sa-danger: #dc2626;
  --sa-danger-hover-bg: #fef2f2;
  --sa-danger-hover-fg: #b91c1c;
  --sa-line-rgb: 15, 23, 42;
  --sa-modal-radius: 12px;
  --sa-modal-radius-compact: 10px;
  --accent: rgb(37, 99, 235);
  --accent-rgb: 37, 99, 235;
  --accent-strong: #1d4ed8;
  --accent-text: #1d4ed8;
  --accent-soft: #dbeafe;
  --accent-muted: #eff6ff;
  --page-background: var(--sa-page, #f2f2f2);
  --dashboard-page-background: var(--sa-page, #f2f2f2);
  --dashboard-page-background-rgb: 242, 242, 242;
  --dashboard-header-text: var(--text-primary);
  --dashboard-header-copy: var(--text-secondary);
  --dashboard-header-label: var(--accent-text);
  --dashboard-header-tool-color: var(--accent-text);
  --dashboard-header-tool-hover-color: var(--accent-strong);
  --dashboard-header-profile-bg: #ffffff;
  --dashboard-header-profile-border: rgba(15, 23, 42, 0.08);
  --dashboard-header-profile-title: var(--text-primary);
  --dashboard-header-profile-copy: var(--text-secondary);
  --dashboard-header-avatar-bg: #ffffff;
  --dashboard-header-avatar-border: rgba(15, 23, 42, 0.12);
  --dashboard-header-avatar-text: var(--text-primary);
  --dashboard-header-nav-toggle-bg: #ffffff;
  --dashboard-header-nav-toggle-border: rgba(15, 23, 42, 0.12);
  --dashboard-header-nav-toggle-text: var(--text-primary);
  --dashboard-header-nav-toggle-hover-bg: #ffffff;
  --dashboard-header-nav-toggle-hover-text: var(--text-primary);
  --surface: #ffffff;
  --surface-soft: #f8fbff;
  --border: #c8d8f2;
  --panel-border: rgba(37, 99, 235, 0.16);
  --text-primary: #162033;
  --text-secondary: #52607a;
  --success: #2f7d4f;
  --shadow: 0 10px 20px rgba(21, 42, 88, 0.06);
  --hero-glow: rgba(37, 99, 235, 0.2);
  --ring: rgba(37, 99, 235, 0.16);
  --button-shadow: 0 7px 15px rgba(37, 99, 235, 0.11);
  --accent-contrast: #ffffff;
  --accent-selected-bg: #ffffff;
  --accent-selected-fg: #000000;
  --accent-button-bg: var(--accent);
  --accent-button-hover-bg: var(--accent-strong);
  --accent-button-gradient-bg: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
  --accent-button-gradient-hover-bg: linear-gradient(135deg, var(--accent-strong) 0%, var(--accent-strong) 100%);
  --table-row-hover-bg: rgba(var(--accent-rgb, 37, 99, 235), 0.055);
  --table-row-hover-shadow: inset 3px 0 0 rgba(var(--accent-rgb, 37, 99, 235), 0.55);
  /* One Super Admin scrollbar source — matches the notification list. */
  --sa-scrollbar-size: 8px;
  --sa-scrollbar-thumb: rgba(15, 23, 42, 0.28);
  --sa-scrollbar-thumb-hover: rgba(15, 23, 42, 0.42);
  --sa-scrollbar-track: transparent;
}button,
.dashboard-link-button,
.theme-link--icon {
  border-radius: 8px;
}
* {
  box-sizing: border-box;
}
html {
  max-width: 100%;
  overflow-x: hidden;
  overflow-y: scroll;
  scrollbar-gutter: stable;
}
body {
  max-width: 100%;
  overflow-x: hidden;
  scrollbar-gutter: stable;
}
html,
body,
* {
  scrollbar-width: thin;
  scrollbar-color: var(--sa-scrollbar-thumb) var(--sa-scrollbar-track);
}
*::-webkit-scrollbar {
  width: var(--sa-scrollbar-size);
  height: var(--sa-scrollbar-size);
}
*::-webkit-scrollbar-track {
  background: var(--sa-scrollbar-track);
}
*::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: var(--sa-scrollbar-thumb);
  background-clip: padding-box;
}
*::-webkit-scrollbar-thumb:hover {
  background: var(--sa-scrollbar-thumb-hover);
  background-clip: padding-box;
}
table tbody tr:not(.table-row-no-hover):not(.employee-attendance-table__empty-row) {
  transition: background-color 140ms ease, box-shadow 140ms ease;
}
table tbody tr:hover:not(.table-row-no-hover):not(.employee-attendance-table__empty-row) > th,
table tbody tr:hover:not(.table-row-no-hover):not(.employee-attendance-table__empty-row) > td,
table tbody tr:focus-within:not(.table-row-no-hover):not(.employee-attendance-table__empty-row) > th,
table tbody tr:focus-within:not(.table-row-no-hover):not(.employee-attendance-table__empty-row) > td {
  background: var(--table-row-hover-bg);
}
table tbody tr:hover:not(.table-row-no-hover):not(.employee-attendance-table__empty-row) > :first-child,
table tbody tr:focus-within:not(.table-row-no-hover):not(.employee-attendance-table__empty-row) > :first-child {
  box-shadow: var(--table-row-hover-shadow);
}
[hidden] {
  display: none !important;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: visible;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-family: var(--admin-seller-font);
  font-optical-sizing: auto;
  font-synthesis: none;
  -webkit-font-smoothing: auto;
  -moz-osx-font-smoothing: auto;
  text-rendering: auto;
  background: var(--page-background);
  color: var(--text-primary);
}
body.modal-open {
  overflow-x: hidden;
  scrollbar-gutter: stable;
}
/* === SA shared dashboard/shell selectors inlined from styles.css === */
button,
.dashboard-link-button,
.theme-link--icon {
  border-radius: 8px !important;
}
.page-shell {
  width: min(960px, calc(100% - 32px));
  margin: 0 auto;
  padding: 32px 0 0px;
}
.page-shell--narrow {
  width: min(440px, calc(100% - 24px));
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 24px 0;
}
.hero {
  margin-bottom: 22px;
}
.hero--sticky {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--dashboard-page-background);
  padding: 16px 0;
  margin: 0 -24px;
  padding-left: 24px;
  padding-right: 24px;
  border-bottom: 1px solid var(--border);
}
.hero--compact {
  margin-bottom: 18px;
  text-align: center;
}
.hero--compact .hero-copy {
  margin-left: auto;
  margin-right: auto;
}
.hero-actions {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}
.hero-shortcuts {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.hero h1 {
  margin: 0;
  font-size: 48px;
}
.panel h2 {
  margin: 0;
  font-size: 42px;
  font-weight: 500;
}
.hero-copy {
  max-width: 560px;
  margin: 10px 0 0;
  color: var(--text-secondary);
  line-height: 1.6;
}
.panel {
  padding: 22px;
  margin-bottom: 18px;
  background: var(--dashboard-page-background);
  border-radius: 24px;
}
.panel-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 18px;
}
html.notification-drawer-open body .dashboard-shell--panel-nav [data-settings-menu],
body.notification-drawer-open .dashboard-shell--panel-nav [data-settings-menu],
html.notification-drawer-open body .dashboard-shell--panel-nav .settings-menu,
body.notification-drawer-open .dashboard-shell--panel-nav .settings-menu {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.universal-main-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.universal-main-header__controls,
.universal-main-header__actions,
.universal-main-header__workspace {
  display: flex;
  align-items: center;
  min-width: 0;
}
.universal-main-header__workspace {
  flex: 0 0 auto;
}
.universal-main-header__actions {
  flex: 0 0 auto;
  margin-left: auto;
  justify-content: flex-end;
}
.product-panel-toolbar {
  position: relative;
  z-index: 140;
  display: grid;
  gap: 16px;
  padding: 16px 20px;
  margin-bottom: 18px;
  border: 0;
  border-radius: 12px;
  background: var(--sa-surface-high, #f3f4f6);
  box-shadow: none;
  backdrop-filter: none;
}
.product-panel-toolbar__heading {
  margin-bottom: 0;
  align-items: center;
  gap: 16px;
}
.product-panel-toolbar__heading h2 {
  font-size: 48px;
  line-height: 1.08;
}
.product-panel-toolbar__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}
/* ito pwedi idelete */
.product-status-shell .product-panel-toolbar__search {
  flex: 1 1 480px;
  min-height: 56px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  border: 0;
  border-radius: 8px;
  background: var(--sa-surface-high, #f3f4f6);
  box-shadow: none;
}
.product-status-shell .product-panel-toolbar__search:focus-within {
  border-color: transparent;
  box-shadow:
    0 0 0 1px rgba(15, 23, 42, 0.16),
    0 0 0 4px rgba(15, 23, 42, 0.06);
  background: var(--sa-surface-high, #f3f4f6);
  outline: none;
}
.product-status-shell .product-panel-toolbar__search-icon {
  width: 20px;
  height: 20px;
  color: var(--text-secondary);
}
.product-status-shell .product-panel-toolbar__search-icon svg {
  width: 100%;
  height: 100%;
}
.product-status-shell .product-panel-toolbar__search-icon i {
  font-size: 18px;
  line-height: 1;
}
.product-status-shell .product-panel-toolbar__search input[type="search"] {
  width: 100%;
  min-width: 0;
  font-size: 15px;
  font-weight: 500;
  color: var(--text-primary);
  padding: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}
.product-status-shell .product-panel-toolbar__search input[type="search"]:focus {
  box-shadow: none !important;
}
/* hanggang dito */

.universal-search .product-panel-toolbar__search-icon {
  width: 20px;
  height: 20px;
  color: var(--text-secondary, #6b7280);
}
.universal-search .product-panel-toolbar__search-icon svg {
  width: 100%;
  height: 100%;
  display: block;
}
.product-panel-toolbar__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 10px;
}
.product-panel-toolbar__nav-toggle,
.product-panel-toolbar__nav-backdrop {
  display: none;
}
.product-panel-toolbar__nav-toggle {
  width: 48px;
  min-width: 48px;
  min-height: 48px;
  padding: 0;
  position: relative;
  overflow: visible;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: var(--sa-surface, #ffffff);
  color: var(--text-primary);
  border: 1px solid rgba(var(--sa-line-rgb, 15, 23, 42), 0.12);
  box-shadow: none;
}
.product-panel-toolbar__nav-toggle svg {
  width: 22px;
  height: 22px;
  display: block;
  transform: scale(1.015);
  transform-origin: center;
  transition:
    width 180ms ease,
    height 180ms ease,
    transform 180ms ease;
}
.product-panel-toolbar__nav-toggle:hover svg,
.product-panel-toolbar__nav-toggle:focus-visible svg {
  width: 30px;
  height: 30px;
}
.product-panel-toolbar__icon-button {
  width: 56px;
  min-width: 56px;
  min-height: 56px;
  border-radius: 18px;
  background: var(--sa-surface, #ffffff);
}
.product-panel-toolbar__profile {
  min-width: 220px;
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border: 1px solid rgba(var(--accent-rgb), 0.1);
  border-radius: 20px;
  background: var(--sa-surface, #ffffff);
}
.product-panel-toolbar__avatar {
  position: relative;
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: visible;
  border: 1px solid rgba(var(--sa-line-rgb, 15, 23, 42), 0.12);
  border-radius: 999px;
  background: var(--sa-surface, #ffffff);
  color: var(--text-primary);
  font-weight: 800;
  letter-spacing: 0.04em;
  box-shadow: 0 12px 28px rgba(var(--accent-rgb), 0.2);
}
.product-panel-toolbar__avatar[data-employee-workspace-avatar="true"]::after {
  content: "";
  position: absolute;
  right: -2px;
  bottom: -2px;
  z-index: 5;
  width: 12px;
  height: 12px;
  border: 2px solid #ffffff;
  border-radius: 999px;
  background: #22c55e;
  box-shadow: 0 0 0 1px rgba(34, 197, 94, 0.18);
}
.product-panel-toolbar__avatar-image {
  display: block;
  width: 100%;
  height: 100%;
  padding: 0;
  border-radius: inherit;
  object-fit: cover;
  object-position: center;
}
.product-panel-toolbar__avatar-placeholder {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  overflow: hidden;
  font-size: 13px;
  line-height: 1;
}
.product-panel-toolbar__avatar-placeholder svg {
  width: 22px;
  height: 22px;
  display: block;
}
.product-panel-toolbar__profile-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.product-panel-toolbar__profile-copy strong {
  font-size: 14px;
  color: var(--text-primary);
}
.product-panel-toolbar__profile-copy span {
  font-size: 12px;
  color: var(--text-secondary);
}
.hero .product-panel-toolbar__profile {
  min-width: 0;
  width: auto;
  flex: 0 1 auto;
  padding: 8px 12px;
  border: none;
  border-radius: 8px;
  background: var(--sa-surface, #ffffff);
  box-shadow: none;
  outline: none;
}
.hero .product-panel-toolbar__avatar {
  box-shadow: none;
  outline: none;
}
/* ito pwedi idelete */
.product-status-shell .dashboard-content.is-product-list-notification-focus-active {
  --product-list-focus-left: -100px;
  --product-list-focus-top: -100px;
  --product-list-focus-width: 0px;
  --product-list-focus-height: 0px;
  position: relative;
  isolation: isolate;
}
.product-status-shell .dashboard-content.is-product-list-notification-focus-active::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: rgba(255, 255, 255, 0.7);
  -webkit-backdrop-filter: blur(1.6px);
  backdrop-filter: blur(1.6px);
  -webkit-mask-image:
    linear-gradient(#000 0 0),
    linear-gradient(#000 0 0);
  -webkit-mask-position:
    0 0,
    var(--product-list-focus-left) var(--product-list-focus-top);
  -webkit-mask-size:
    100% 100%,
    var(--product-list-focus-width) var(--product-list-focus-height);
  -webkit-mask-repeat: no-repeat;
  -webkit-mask-composite: xor;
  mask-image:
    linear-gradient(#000 0 0),
    linear-gradient(#000 0 0);
  mask-position:
    0 0,
    var(--product-list-focus-left) var(--product-list-focus-top);
  mask-size:
    100% 100%,
    var(--product-list-focus-width) var(--product-list-focus-height);
  mask-repeat: no-repeat;
  mask-composite: exclude;
  pointer-events: none;
}
.product-status-shell
  .dashboard-content.is-product-list-notification-focus-active
  .product-list.is-notification-focus-active {
  z-index: 1000;
}
.product-status-shell
  .dashboard-content.is-product-list-notification-focus-active
  .product-list.is-notification-focus-active::before {
  display: none;
}
.product-status-shell
  .dashboard-content.is-product-list-notification-focus-active
  .product-list.is-notification-focus-active
  > .product-card.is-notification-focus-pop,
.product-status-shell
  .dashboard-content.is-product-list-notification-focus-active
  .product-list.is-notification-focus-active
  > .product-card.is-notification-focus-pop:hover,
.product-status-shell
  .dashboard-content.is-product-list-notification-focus-active
  .product-list.is-notification-focus-active
  > .product-card.is-notification-focus-pop:focus-visible,
.product-status-shell
  .dashboard-content.is-product-list-notification-focus-active
  .product-list.is-notification-focus-active
  > .product-card.is-inactive.is-notification-focus-pop,
.product-status-shell
  .dashboard-content.is-product-list-notification-focus-active
  .product-list.is-notification-focus-active
  > .product-card.is-inactive.is-notification-focus-pop:hover,
.product-status-shell
  .dashboard-content.is-product-list-notification-focus-active
  .product-list.is-notification-focus-active
  > .product-card.is-inactive.is-notification-focus-pop:focus-visible {
  position: relative !important;
  z-index: 1100 !important;
  opacity: 1 !important;
  filter: none !important;
  animation: product-list-notification-focus-pop-no-ring 1.55s ease both !important;
  border-color: rgba(var(--sa-line-rgb, 15, 23, 42), 0.1) !important;
  background: var(--sa-surface, #ffffff) !important;
  box-shadow:
    0 12px 24px rgba(15, 23, 42, 0.16),
    0 3px 8px rgba(15, 23, 42, 0.1) !important;
  outline: none !important;
  transform-origin: center center !important;
}
