.concern-panel .panel-heading {
  align-items: flex-start;
}
.concern-panel .panel-heading h2 {
  font-size: 28px;
  line-height: 1.12;
}
.product-variant-addon-picker__chips .empty-state {
  border-radius: 8px;
}
/* ito pwedi idelete */
.dashboard-shell--panel-nav .category-manager-panel {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: auto;
  z-index: 240;
  width: min(var(--category-manager-panel-width, 360px), 100vw);
  max-width: 100vw;
  max-height: none;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  padding: 0;
  border: 0;
  border-left: 1px solid rgba(var(--sa-line-rgb, 15, 23, 42), 0.12);
  border-radius: 0 !important;
  background: var(--sa-surface, #ffffff) !important;
  box-shadow: -18px 0 36px rgba(15, 23, 42, 0.12) !important;
  backdrop-filter: blur(14px) !important;
  align-content: start;
  gap: 0;
  color: var(--text-primary);
  overscroll-behavior: contain;
  opacity: 0;
  pointer-events: none;
  transform: translateX(100%);
  transition:
    opacity 180ms ease,
    transform 220ms cubic-bezier(0.22, 1, 0.36, 1);
}
.dashboard-shell--panel-nav .category-manager-panel.is-open {
  opacity: 1;
  pointer-events: auto;
  transform: translateX(0);
}
.dashboard-shell--panel-nav .category-manager-panel.is-closing {
  opacity: 0;
  pointer-events: none;
  transform: translateX(100%);
}
.dashboard-shell--panel-nav .category-manager-panel[hidden] {
  display: none !important;
}
.dashboard-shell--panel-nav .category-manager-panel .panel-heading {
  position: relative;
  align-items: center;
  justify-content: space-between;
  padding-right: 0;
  margin-bottom: 0;
}
.dashboard-shell--panel-nav .category-manager-panel__header-shell {
  display: grid;
  gap: 18px;
  padding: 22px 18px 16px;
  border-bottom: 1px solid rgba(var(--sa-line-rgb, 15, 23, 42), 0.08);
  background: var(--sa-surface, #ffffff);
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
  position: relative;
  z-index: 1;
}
.dashboard-shell--panel-nav .category-manager-panel .panel-heading h2,
.dashboard-shell--panel-nav .category-manager-panel .panel-copy {
  margin: 0;
}
.dashboard-shell--panel-nav .category-manager-panel .panel-heading h2 {
  font-size: 28px;
}
.dashboard-shell--panel-nav .category-manager-panel .panel-copy {
  color: var(--text-secondary);
}
.dashboard-shell--panel-nav .category-manager-panel .section-label {
  display: none;
}
/* hanggang dito */

.dashboard-shell--panel-nav .slider-drawer__close,
.login-page-shell--settings-drawer .slider-drawer__close {
  position: static;
  top: auto;
  right: auto;
  flex: 0 0 auto;
  margin-left: auto;
  z-index: 1;
}
.dashboard-shell--panel-nav .slider-drawer__close svg,
