/* === Unified Super Admin summary cards (single source) ===
 * Edit ONLY the CSS variables below to restyle every SA summary card
 * (Companies, Product Review, Partners, AI, Feedback, User Data).
 * Card chrome + icon shell/colors live here â€” do not re-declare
 * height/padding/icon/svg rules per panel elsewhere.
 */
:root {
  --super-admin-stat-height: 102px;
  --super-admin-stat-padding: 16px;
  --super-admin-stat-radius: 8px;
  --super-admin-stat-border: 1px solid rgba(var(--sa-line-rgb, 15, 23, 42), 0.16);
  --super-admin-stat-shadow: 0 18px 36px rgba(15, 23, 42, 0.06);
  --super-admin-stats-gap: 12px;
  --super-admin-stats-margin: 0 0 18px;
  --super-admin-stat-icon-size: 44px;
  --super-admin-stat-icon-svg-size: 30px;
  --super-admin-stat-icon-bg: var(--sa-surface, #ffffff);
  --super-admin-stat-icon-accent: var(--accent);
  --super-admin-stat-icon-active: #15803d;
  --super-admin-stat-icon-online: #346e90;
  --super-admin-stat-icon-danger: #b91c1c;
  --super-admin-stat-icon-warning: #b45309;
}
.super-admin-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: var(--super-admin-stats-gap);
}
/* One selector list for every SA summary card row */
body.super-admin-page :is(.super-admin-company-stats, .super-admin-product-request-stats, .partner-data-company-stats, .buyer-data-company-stats) {
  margin: var(--super-admin-stats-margin);
}
/* One selector list for every SA summary card */
body.super-admin-page :is(.super-admin-company-stats, .super-admin-product-request-stats, .partner-data-company-stats, .buyer-data-company-stats) .super-admin-stat {
  box-sizing: border-box;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  grid-template-areas:
    "icon label"
    "icon value"
    "icon trend";
  column-gap: 12px;
  row-gap: 5px;
  align-items: center;
  align-content: center;
  min-width: 0;
  height: var(--super-admin-stat-height);
  min-height: var(--super-admin-stat-height);
  max-height: var(--super-admin-stat-height);
  padding: var(--super-admin-stat-padding);
  border: var(--super-admin-stat-border);
  border-radius: var(--super-admin-stat-radius);
  background: var(--sa-surface, #ffffff);
  box-shadow: var(--super-admin-stat-shadow);
