/* One selector list for every SA summary icon + svg */
body.super-admin-page :is(.super-admin-company-stats, .super-admin-product-request-stats, .partner-data-company-stats, .buyer-data-company-stats) .super-admin-stat__icon {
  grid-area: icon;
  display: inline-grid;
  place-items: center;
  align-self: start;
  width: var(--super-admin-stat-icon-size);
  height: var(--super-admin-stat-icon-size);
  padding-top: 19px;
  border-radius: 999px;
  background: var(--super-admin-stat-icon-bg);
  color: var(--super-admin-stat-icon-accent);
  text-transform: none;
}
body.super-admin-page :is(.super-admin-company-stats, .super-admin-product-request-stats, .partner-data-company-stats, .buyer-data-company-stats) .super-admin-stat__icon svg {
  width: var(--super-admin-stat-icon-svg-size);
