/* Shared Super Admin modal popup — single animation source for every modal view. */
@keyframes sa-modal-popup {
  from {
    opacity: 0;
    transform: var(--sa-modal-from, translateY(18px) scale(0.96));
  }
  to {
    opacity: 1;
    transform: var(--sa-modal-to, translateY(0) scale(1));
  }
}
@keyframes sa-modal-backdrop-in {
  from,
  to {
    opacity: 1;
  }
}
body.super-admin-page {
  --sa-modal-from: translateY(18px) scale(0.96);
  --sa-modal-to: translateY(0) scale(1);
  --sa-modal-popup: sa-modal-popup 220ms cubic-bezier(0.22, 1, 0.36, 1) both;
  --sa-modal-backdrop: sa-modal-backdrop-in 1ms linear both;
}
body.super-admin-page :is(.super-admin-ban-modal, .buyer-data-modal) {
  --sa-modal-from: translate(-50%, calc(-50% + 14px)) scale(0.96);
  --sa-modal-to: translate(-50%, -50%) scale(1);
}
body.super-admin-page :is(
  .theme-modal-overlay,
  .validation-modal-overlay,
  .super-admin-validation-modal-overlay,
  .super-admin-ban-modal-overlay,
