/* === Unified Super Admin pagination (single source) ===
 * Every SA pager uses .super-admin-pagination. Edit ONLY these variables
 * (and the rules below) to restyle Companies,
User Data,
Partners,
* Product Requests,
and Feedback pagers together.
 */
:root {
  --super-admin-pagination-gap: 7px;
  --super-admin-pagination-btn-size: 32px;
  --super-admin-pagination-btn-radius: 5px;
  --super-admin-pagination-btn-border: 1px solid var(--sa-outline, #e5e7eb);
  --super-admin-pagination-btn-bg: var(--sa-surface, #ffffff);
  --super-admin-pagination-btn-color: var(--sa-on-variant, #4b5563);
  --super-admin-pagination-btn-size-text: 10px;
  --super-admin-pagination-btn-weight: 700;
  --super-admin-pagination-icon-size: 14px;
  --super-admin-pagination-ellipsis-width: 26px;
  --super-admin-pagination-ellipsis-color: var(--sa-hint, #64748b);
  --super-admin-list-view-page-size: 10;
}
body.super-admin-page .super-admin-pagination {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--super-admin-pagination-gap);
  flex-wrap: nowrap;
  min-width: 0;
  min-height: var(--super-admin-pagination-btn-size);
}
body.super-admin-page .super-admin-pagination[hidden] {
  display: none;
}
body.super-admin-page .super-admin-pagination button {
  display: inline-grid;
  place-items: center;
  width: var(--super-admin-pagination-btn-size);
  height: var(--super-admin-pagination-btn-size);
  min-width: var(--super-admin-pagination-btn-size);
  min-height: var(--super-admin-pagination-btn-size);
  padding: 0;
  border: var(--super-admin-pagination-btn-border);
  border-radius: var(--super-admin-pagination-btn-radius) !important;
  background: var(--super-admin-pagination-btn-bg);
  color: var(--super-admin-pagination-btn-color);
  font-size: var(--super-admin-pagination-btn-size-text);
  font-weight: var(--super-admin-pagination-btn-weight);
  box-shadow: none;
}
body.super-admin-page .super-admin-pagination button svg {
  width: var(--super-admin-pagination-icon-size);
  height: var(--super-admin-pagination-icon-size);
}
body.super-admin-page .super-admin-pagination button:hover:not(:disabled),
body.super-admin-page .super-admin-pagination button:focus-visible:not(:disabled),
body.super-admin-page .super-admin-pagination button.is-active {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--accent-contrast, #ffffff);
}
body.super-admin-page .super-admin-pagination button:disabled {
  color: #c0c7d1;
  cursor: not-allowed;
  opacity: 0.72;
}
body.super-admin-page .super-admin-pagination .super-admin-pagination__ellipsis {
  display: inline-grid;
  width: var(--super-admin-pagination-ellipsis-width);
  height: var(--super-admin-pagination-btn-size);
  place-items: center;
  color: var(--super-admin-pagination-ellipsis-color);
  font-size: var(--super-admin-pagination-btn-size-text);
  font-weight: var(--super-admin-pagination-btn-weight);
}
.feedback-note.error {
  color: var(--sa-danger-hover-fg, #b91c1c);
}


@media (max-width: 1180px) {
  .super-admin-grid,
.super-admin-row {
    grid-template-columns: 1fr;
  }


  .super-admin-company-list {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }


  .super-admin-store-type-list.category-list {
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
