.sa-flip-tile {
  --flip-radius: 9px;
  position: relative;
  isolation: isolate;
  display: block;
  box-sizing: border-box;
  overflow: visible;
  border: 0;
  border-radius: var(--flip-radius);
  background: transparent;
  color: #f8fafc;
  box-shadow: none;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  text-shadow: 0 2px 2px rgba(0, 0, 0, 0.75);
  perspective: 160px;
  filter: drop-shadow(0 5px 6px rgba(15, 23, 42, 0.3));
}
.sa-flip-tile::before {
  content: "";
  position: absolute;
  top: 50%;
  right: -2px;
  left: -2px;
  z-index: 6;
  height: 6px;
  border-radius: 1px;
  background:
    linear-gradient(90deg, #3a3a3a 0 2px, #0c0c0c 2px 4px, transparent 4px calc(100% - 4px), #0c0c0c calc(100% - 4px) calc(100% - 2px), #3a3a3a calc(100% - 2px)),
    linear-gradient(180deg, transparent 0 2px, rgba(0, 0, 0, 0.92) 2px 3px, rgba(255, 255, 255, 0.08) 3px 4px, transparent 4px);
  transform: translateY(-50%);
  pointer-events: none;
}
.sa-flip-tile__flap {
  position: absolute;
  right: 0;
  left: 0;
  z-index: 1;
  height: 50%;
  box-sizing: border-box;
  overflow: hidden;
  backface-visibility: hidden;
}
.sa-flip-tile__flap > span {
  position: absolute;
  right: 0;
  left: 0;
  display: grid;
  height: 200%;
  place-items: center;
}
.sa-flip-tile__flap::after {
  content: "";
  position: absolute;
  inset: 0;
  background: #000;
  opacity: 0;
  pointer-events: none;
}
.sa-flip-tile__flap.is-top {
  top: 0;
  border-radius: var(--flip-radius) var(--flip-radius) 0 0;
  background: linear-gradient(180deg, #363636 0%, #2a2a2a 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    inset 1px 0 0 rgba(255, 255, 255, 0.04),
    inset -1px 0 0 rgba(255, 255, 255, 0.04);
  transform-origin: 50% 100%;
}
.sa-flip-tile__flap.is-top > span {
  top: 0;
}
.sa-flip-tile__flap.is-bottom {
  bottom: 0;
  border-radius: 0 0 var(--flip-radius) var(--flip-radius);
  background: linear-gradient(180deg, #222 0%, #1a1a1a 100%);
  box-shadow:
    inset 0 -1px 0 rgba(0, 0, 0, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  transform-origin: 50% 0%;
}
.sa-flip-tile__flap.is-bottom > span {
  bottom: 0;
}
.sa-flip-tile__flap.is-top.is-flipping {
  z-index: 4;
  animation: sa-voucher-flap-fall 0.3s cubic-bezier(0.55, 0.06, 0.85, 0.45) forwards;
  will-change: transform;
}
.sa-flip-tile__flap.is-top.is-flipping::after {
  animation: sa-voucher-flap-dim 0.3s ease-in forwards;
}
.sa-flip-tile__flap.is-bottom.is-flipping {
  z-index: 4;
  transform: rotateX(90deg);
  animation: sa-voucher-flap-land 0.42s cubic-bezier(0.3, 0.6, 0.4, 1) 0.28s forwards;
  will-change: transform;
}
.sa-flip-tile__flap.is-bottom.is-flipping::after {
  opacity: 0.55;
  animation: sa-voucher-flap-light 0.3s ease-out 0.28s forwards;
}
.sa-flip-tile.is-flipping > .sa-flip-tile__flap.is-top:not(.is-flipping)::after {
  animation: sa-voucher-flap-reveal 0.3s ease-out forwards;
}
.sa-flip-tile.is-flipping > .sa-flip-tile__flap.is-bottom:not(.is-flipping)::after {
  animation: sa-voucher-flap-shade 0.42s ease-in 0.1s forwards;
}
@keyframes sa-voucher-flap-fall {
  from {
    transform: rotateX(0deg);
  }
  to {
    transform: rotateX(-90deg);
  }
}
@keyframes sa-voucher-flap-land {
  0% {
    transform: rotateX(90deg);
  }
  62% {
    transform: rotateX(0deg);
  }
  80% {
    transform: rotateX(14deg);
  }
  100% {
    transform: rotateX(0deg);
  }
}
@keyframes sa-voucher-flap-dim {
  to {
    opacity: 0.6;
  }
}
@keyframes sa-voucher-flap-light {
  to {
    opacity: 0;
  }
}
@keyframes sa-voucher-flap-reveal {
  from {
    opacity: 0.5;
  }
  to {
    opacity: 0;
  }
}
@keyframes sa-voucher-flap-shade {
  0% {
    opacity: 0;
  }
  70% {
    opacity: 0.4;
  }
  100% {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sa-flip-tile__flap.is-flipping,
  .sa-flip-tile__flap::after {
    animation: none !important;
  }
}
