body.super-admin-page .sa-flash-photo-fan.payment-platform-fan__stack .sa-flash-photo-fan__card:not(.is-empty):hover {
  z-index: 60 !important;
  translate: 0 -8%;
  filter: none;
}
@media (prefers-reduced-motion: reduce) {
  body.super-admin-page .sa-flash-photo-fan.payment-platform-fan__stack .sa-flash-photo-fan__card:not(.is-empty):hover {
    translate: none;
  }
}
/* The fan spreads to the media's content box (30px padding each side); the
   outermost card's half width plus tilt reaches about 0.82 card widths past its center. */
body.super-admin-page .sa-flash-photo-fan.is-viewable.payment-platform-fan__stack {
  --fan-card-w: clamp(56px, 24cqi, 118px);
  width: 100cqi;
  margin-bottom: calc(var(--fan-card-w) * 0.24);
}
body.super-admin-page .payment-platform-showcase__media::before {
  display: none;
}
body.super-admin-page .payment-platform-fan__stack .sa-flash-photo-fan__card,
body.super-admin-page .payment-platform-showcase:hover .payment-platform-fan__stack .sa-flash-photo-fan__card,
body.super-admin-page .payment-platform-showcase:focus-within .payment-platform-fan__stack .sa-flash-photo-fan__card {
  --fan-spread: clamp(0px, calc((50cqi - var(--fan-card-w) * 0.82) / var(--fan-reach, 1)), calc(var(--fan-card-w) * 0.6));
  --fan-tilt: 2deg;
  filter: brightness(calc(1 - var(--fan-level) * 0.025));
  transform:
    translate(-50%, -50%)
    translateX(calc((var(--fan-side) * var(--fan-level) - var(--fan-shift, 0)) * var(--fan-spread)))
    translateY(calc(var(--fan-level) * 2%))
    rotate(calc(var(--fan-side) * var(--fan-level) * var(--fan-tilt)));
}
body.super-admin-page .payment-platform-fan__stack .sa-flash-photo-fan__card.is-thumbed {
  animation-name: payment-platform-fan-flip;
}
@keyframes payment-platform-fan-flip {
  0% {
    translate: 0 0;
    rotate: 0deg;
    animation-timing-function: cubic-bezier(0.33, 0, 0.3, 1);
  }
  40% {
    translate: calc(var(--thumb-dir, 1) * 10%) -20%;
    rotate: calc(var(--thumb-dir, 1) * 5deg);
    animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1);
  }
  100% {
    translate: 0 0;
    rotate: 0deg;
  }
}
html[data-sa-scheme="dark"] body.super-admin-page .payment-platform-fan__stack .sa-flash-photo-fan__card {
