  min-width: 0;
}
.payment-history-row__title,
.payment-history-row__meta,
.payment-history-row__ref {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.payment-history-row__title {
  font-size: 14px;
  font-weight: 500;
}
.payment-history-row__meta {
  color: var(--sa-muted, #475569);
  font-size: 12px;
}
.payment-history-row__ref {
  color: var(--sa-hint, #64748b);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 11px;
}
.payment-history-row__side {
  display: grid;
  justify-items: end;
  gap: 4px;
}
.payment-history-row__side strong {
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  white-space: nowrap;
}
.payment-history-status {
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1.5;
}
:is(.payment-history-row__icon, .payment-history-status).is-paid {
  background: var(--tone-paid-bg);
  color: var(--tone-paid-fg);
}
:is(.payment-history-row__icon, .payment-history-status).is-pending {
  background: var(--tone-pending-bg);
  color: var(--tone-pending-fg);
}
:is(.payment-history-row__icon, .payment-history-status).is-failed {
  background: var(--tone-failed-bg);
  color: var(--tone-failed-fg);
}
:is(.payment-history-row__icon, .payment-history-status).is-refunded {
  background: var(--tone-refunded-bg);
  color: var(--tone-refunded-fg);
}
:is(.payment-history-row__icon, .payment-history-status).is-cancelled {
  background: var(--tone-cancelled-bg);
  color: var(--tone-cancelled-fg);
}
:is(.payment-history-row, .payment-history-stat).is-skeleton {
  min-height: 64px;
  border: 0;
  border-radius: 12px;
  background: linear-gradient(
    90deg,
    var(--sa-surface-low, #f1f5f9) 25%,
    rgba(var(--sa-line-rgb, 15, 23, 42), 0.07) 50%,
    var(--sa-surface-low, #f1f5f9) 75%
  );
  background-size: 200% 100%;
  animation: payment-history-shimmer 1.2s ease-in-out infinite;
}
.payment-history-row.is-skeleton {
  display: block;
  margin: 8px 0;
}
@keyframes payment-history-shimmer {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}
.payment-history-panel__empty {
  display: grid;
  justify-items: center;
  gap: 6px;
  padding: 48px 16px;
  color: var(--sa-hint, #64748b);
  font-size: 13px;
  text-align: center;
}
.payment-history-panel__empty strong {
  color: var(--sa-on-surface, #111827);
  font-size: 15px;
  font-weight: 600;
}
.payment-history-panel__empty .payment-history-chip {
  margin-top: 8px;
}
.payment-history-panel__empty-icon {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  margin-bottom: 4px;
  border-radius: 999px;
  background: var(--sa-surface-low, #f1f5f9);
  color: var(--sa-muted, #475569);
}
.payment-history-panel__empty-icon svg {
  width: 24px;
  height: 24px;
}
.payment-history-panel__empty.is-error strong {
  color: var(--tone-failed-fg);
}
/* Not enough room to dock beside the drawer: cover it instead. */
@media (max-width: 760px) {
  body.super-admin-page > .payment-history-panel {
    right: 0;
    z-index: 2320;
    width: 100vw;
    border-left: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  body.super-admin-page > .payment-history-panel,
  body.super-admin-page .payment-platform-row__history {
    transition: none;
  }
  :is(.payment-history-row, .payment-history-stat).is-skeleton,
  .payment-history-panel.is-loading [data-payment-history-refresh] svg {
    animation: none;
  }
}
html[data-sa-scheme="dark"] body.super-admin-page > .payment-history-panel {
  --tone-paid-bg: rgba(34, 197, 94, 0.16);
  --tone-paid-fg: #4ade80;
  --tone-pending-bg: rgba(245, 158, 11, 0.16);
  --tone-pending-fg: #fbbf24;
  --tone-failed-bg: rgba(239, 68, 68, 0.16);
  --tone-failed-fg: #f87171;
  --tone-refunded-bg: rgba(99, 102, 241, 0.18);
  --tone-refunded-fg: #a5b4fc;
  --tone-cancelled-bg: var(--sa-surface-high);
  --tone-cancelled-fg: var(--sa-muted);
  border-left-color: var(--sa-outline);
  box-shadow:
    inset -1px 0 0 var(--sa-outline),
    -24px 0 48px -28px rgba(0, 0, 0, 0.7);
}
html[data-sa-scheme="dark"] body.super-admin-page .payment-history-panel__toolbar {
  background: var(--sa-surface);
  box-shadow: 0 1px 0 var(--sa-outline);
}
html[data-sa-scheme="dark"] body.super-admin-page .payment-history-panel__switch {
  border-color: var(--sa-outline);
  background: var(--sa-surface);
}
html[data-sa-scheme="dark"] body.super-admin-page .payment-history-panel__switch.is-off,
html[data-sa-scheme="dark"] body.super-admin-page :is(.payment-history-stat, .payment-history-panel__logo, .payment-history-panel__empty-icon) {
  border-color: var(--sa-outline);
  background: var(--sa-surface-high);
}
html[data-sa-scheme="dark"] body.super-admin-page .payment-history-panel .sa-flash-registered-drawer__search {
  border-color: var(--sa-outline);
  background: #282a2c;
}
html[data-sa-scheme="dark"] body.super-admin-page :is(.payment-history-row, .payment-history-chip) {
  border-color: var(--sa-outline);
}
html[data-sa-scheme="dark"] body.super-admin-page :is(.payment-history-chip:hover, .payment-history-panel__icon-button:hover, .payment-platform-row:hover, .payment-platform-row:focus-within) {
  background: var(--sa-surface-high);
}
html[data-sa-scheme="dark"] body.super-admin-page .payment-platform-row.is-history-open {
  background: rgba(var(--accent-rgb, 37, 99, 235), 0.16);
}
html[data-sa-scheme="dark"] body.super-admin-page .payment-platform-row__history {
  border-color: transparent;
  background: transparent;
  color: var(--sa-hint);
}
html[data-sa-scheme="dark"] body.super-admin-page .payment-platform-row__history:is(:hover, :focus-visible) {
  background: transparent;
  color: var(--accent);
}
html[data-sa-scheme="dark"] body.super-admin-page .payment-platform-row.is-history-open .payment-platform-row__history {
  border-color: transparent;
  background: transparent;
  color: var(--accent);
}
html[data-sa-scheme="dark"] body.super-admin-page :is(.payment-history-row, .payment-history-stat).is-skeleton {
  background: linear-gradient(90deg, var(--sa-surface-high) 25%, rgba(255, 255, 255, 0.06) 50%, var(--sa-surface-high) 75%);
  background-size: 200% 100%;
}
